<?php $faqs=json_decode($article['faq_json']??'[]',true)?:[];$sources=json_decode($article['sources_json']??'[]',true)?:[]; ?><div class="container page-stack"><section class="prose"><p class="eyebrow">CONTENT MANAGEMENT</p><h1><?=e($title)?></h1><form method="post" action="/admin/articles/save" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=e((string)($article['id']??0))?>"><label class="form-field">标题<input name="title" id="article-title" value="<?=e($article['title'])?>" required></label><label class="form-field">Slug<input name="slug" value="<?=e($article['slug'])?>" pattern="[a-z0-9-]+" required></label><label class="form-field">SEO Title <span data-title-length></span><input name="seo_title" id="seo-title" value="<?=e($article['seo_title'])?>" required></label><label class="form-field">Meta Description <span data-description-length></span><textarea name="meta_description" id="meta-description" required><?=e($article['meta_description'])?></textarea></label><div class="seo-checklist"><strong>发布前检查（提示，不会阻止保存）</strong><ul><li>Title 长度建议 30–60 字符</li><li>Description 建议简洁、准确，通常不超过 160 字符</li><li>正文包含 H2/H3 与站内链接</li><li>提供相关主题图片及准确的 Alt</li></ul></div><label class="form-field">正文 HTML（允许的标签会安全过滤）<textarea name="content_html" id="article-content" rows="24" required><?=e($article['content_html'])?></textarea></label><label class="form-field">分类<select name="category_ids[]" multiple size="6"><?php foreach($categories as $cat): ?><option value="<?=e((string)$cat['id'])?>" <?=in_array($cat['id'],$selectedCategories??[],false)?'selected':''?>><?=e($cat['name'])?></option><?php endforeach; ?></select></label><label class="form-field">图片路径或 URL<input name="image_url" value="<?=e($article['image_url']??'')?>" placeholder="/uploads/covers/example.svg"></label><label class="form-field">上传新图片（JPG/PNG/WebP/SVG，最大 2MB）<input type="file" name="image_file" accept="image/jpeg,image/png,image/webp,image/svg+xml"></label><label class="form-field">图片替代文本（中文）<input name="image_alt" value="<?=e($article['image_alt']??'')?>"></label><label><input type="checkbox" name="featured" value="1" <?=!empty($article['is_featured'])?'checked':''?>> 设为精选文章</label> <label><input type="checkbox" name="popular" value="1" <?=!empty($article['is_popular'])?'checked':''?>> 设为热门指南</label><label class="form-field">发布时间<input type="datetime-local" name="published_at" value="<?=!empty($article['published_at'])?e(date('Y-m-d\\TH:i',strtotime($article['published_at']))):''?>"></label><h2>FAQ（最多填写有真实帮助的问题）</h2><?php for($i=0;$i<3;$i++): ?><label class="form-field">问题 <?=($i+1)?><input name="faq[<?=$i?>][q]" value="<?=e($faqs[$i]['q']??'')?>"></label><label class="form-field">回答 <?=($i+1)?><textarea name="faq[<?=$i?>][a]" rows="2"><?=e($faqs[$i]['a']??'')?></textarea></label><?php endfor; ?><h2>官方来源链接（最多 4 项）</h2><?php for($i=0;$i<4;$i++): ?><label class="form-field">来源标题<input name="sources[<?=$i?>][title]" value="<?=e($sources[$i]['title']??'')?>"></label><label class="form-field">来源 URL<input type="url" name="sources[<?=$i?>][url]" value="<?=e($sources[$i]['url']??'')?>"></label><?php endfor; ?><label class="form-field">状态<select name="status"><option value="draft" <?=($article['status']??'')==='draft'?'selected':''?>>草稿</option><option value="published" <?=($article['status']??'')==='published'?'selected':''?>>发布</option></select></label><button class="button button-dark" type="submit">保存文章</button>
<button class="button" type="submit" formaction="/admin/articles/preview">预览草稿</button>
<?php if(!empty($article['id']) && ($article['status']??'')==='published'): ?> <a href="/articles/<?=e($article['slug'])?>" target="_blank">查看已发布页面</a><?php endif; ?></form><script>document.addEventListener('DOMContentLoaded',function(){var t=document.getElementById('seo-title'),d=document.getElementById('meta-description');function u(){document.querySelector('[data-title-length]').textContent=t.value.length+' 字符';document.querySelector('[data-description-length]').textContent=d.value.length+' 字符'}t.addEventListener('input',u);d.addEventListener('input',u);u()});</script></section></div>